-- Step 1 of 4 for orders.public_id. Catalog-only: no table rewrite, no backfill, no long lock.
SET lock_timeout = '3s';

-- Nullable on purpose: existing rows are filled in by 0005 and the column is made NOT NULL by 0007.
ALTER TABLE orders ADD COLUMN public_id uuid;

-- Set after ADD COLUMN: a volatile default in ADD COLUMN would rewrite all rows. From here on,
-- every new row gets a value even when the app does not set one.
ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid();

