-- migrate:no-transaction
-- Step 2 of 4 for orders.public_id: fills rows that existed before 0004 set the default.
--
-- Batched: each batch is its own transaction (COMMIT inside the DO block), so each row lock is held
-- for one batch only. Walks the primary key in order. Only touches rows with NULL public_id, so a
-- failed run can simply be re-run and resumes where the data is still NULL.
SET lock_timeout = '3s';

DO $$
DECLARE
  batch_size constant int := 5000;
  last_id bigint := 0;
  batch_max bigint;
BEGIN
  LOOP
    SELECT max(b.id) INTO batch_max
      FROM (SELECT id FROM orders WHERE id > last_id ORDER BY id LIMIT batch_size) AS b;
    EXIT WHEN batch_max IS NULL;

    UPDATE orders
       SET public_id = gen_random_uuid()
     WHERE id > last_id AND id <= batch_max AND public_id IS NULL;

    last_id := batch_max;
    COMMIT;
  END LOOP;
END $$;

